public sealed class CreateEndOfServiceSettlementValidator:AbstractValidator<CreateEndOfServiceSettlementCommand>
{ public CreateEndOfServiceSettlementValidator(){RuleFor(x=>x.Request.EmployeeId).NotEmpty();RuleFor(x=>x.Request.LastWorkingDate).NotEmpty();} }
public sealed class CalculateEndOfServiceSettlementValidator:AbstractValidator<CalculateEndOfServiceSettlementCommand>
{ public CalculateEndOfServiceSettlementValidator(){RuleFor(x=>x.Request.RowVersion).NotEmpty();RuleFor(x=>x.Request.EndOfServiceBenefitAmount).GreaterThanOrEqualTo(0);RuleFor(x=>x.Request.OtherEarningsAmount).GreaterThanOrEqualTo(0);RuleFor(x=>x.Request.OtherDeductionsAmount).GreaterThanOrEqualTo(0);RuleFor(x=>x.Request.LeaveDailyRate).NotNull().GreaterThan(0).When(x=>x.Request.SettleEncashableLeave);} }
public sealed class PayEndOfServiceSettlementValidator:AbstractValidator<PayEndOfServiceSettlementCommand>
{ public PayEndOfServiceSettlementValidator(){RuleFor(x=>x.Request.Amount).GreaterThan(0);RuleFor(x=>x.Request.PaymentMethod).GreaterThan((byte)0);RuleFor(x=>x.Request.SettlementAccountId).NotEmpty();} }

internal static class EosMapping
{
    public static EndOfServiceSettlementDto ToDto(EndOfServiceSettlement x,Employee e,IReadOnlyList<EndOfServiceSettlementLine> lines,IReadOnlyList<PaymentAllocation> allocations)
    {
        var related=allocations.Where(a=>a.TargetDocumentType==AllocationTargetDocumentType.EndOfServiceSettlement&&a.TargetDocumentId==x.Id).ToArray();
        var paid=related.Sum(a=>a.AllocatedAmount);
        var outstanding=Math.Max(0m,x.NetSettlementAmount-paid);
        var paymentStatus=x.NetSettlementAmount<=0||outstanding<=0?"Paid":paid<=0?"Unpaid":"PartiallyPaid";
        return new(x.Id,x.SettlementCode,x.EmployeeId,e.EmployeeCode,e.DisplayName,x.ContractId,x.FinalEmployeePayrollId,x.LastWorkingDate,(byte)x.Status,x.CurrencyId,x.CurrencyCodeSnapshot,x.CurrencySymbolSnapshot,x.CurrencyDecimalPlacesSnapshot,x.OutstandingPayrollAmountSnapshot,x.LeaveSettlementAmount,x.EndOfServiceBenefitAmount,x.OtherEarningsAmount,x.LoanDeductionAmount,x.OtherDeductionsAmount,x.GrossSettlementAmount,x.NetSettlementAmount,x.BaseNetSettlementAmount,paid,outstanding,paymentStatus,x.JournalEntryId,lines.OrderBy(l=>l.LineSequence).Select(l=>new EndOfServiceLineDto(l.Id,l.LineSequence,(byte)l.LineType,l.Description,l.SourceDocumentType,l.SourceDocumentId,l.Quantity,l.Rate,l.Amount,l.DebitPostingRole,l.CreditPostingRole)).ToArray(),Convert.ToBase64String(x.RowVersion));
    }
    public static void Check(string incoming,byte[] current){byte[] v;try{v=Convert.FromBase64String(incoming);}catch(FormatException ex){throw new ConcurrencyException("Row version is invalid.",ex);}if(!v.SequenceEqual(current))throw new ConcurrencyException("End-of-service settlement was changed by another operation.");}
}

public sealed class GetEndOfServiceSettlementsQueryHandler(IReadRepository<EndOfServiceSettlement,Guid> settlements,IReadRepository<EndOfServiceSettlementLine,Guid> lines,IReadRepository<Employee,Guid> employees,IReadRepository<PaymentAllocation,Guid> allocations):IRequestHandler<GetEndOfServiceSettlementsQuery,IReadOnlyList<EndOfServiceSettlementDto>>
{ public async Task<IReadOnlyList<EndOfServiceSettlementDto>> Handle(GetEndOfServiceSettlementsQuery r,CancellationToken ct){var rows=await settlements.ListAsync(new Specification<EndOfServiceSettlement>().Where(x=>(!r.EmployeeId.HasValue||x.EmployeeId==r.EmployeeId.Value)&&(!r.Status.HasValue||(byte)x.Status==r.Status.Value)),ct);var ids=rows.Select(x=>x.Id).ToHashSet();var ls=await lines.ListAsync(new Specification<EndOfServiceSettlementLine>().Where(x=>ids.Contains(x.EndOfServiceSettlementId)),ct);var al=await allocations.ListAsync(new Specification<PaymentAllocation>().Where(x=>x.TargetDocumentType==AllocationTargetDocumentType.EndOfServiceSettlement&&ids.Contains(x.TargetDocumentId)),ct);var emps=(await employees.ListAsync(cancellationToken:ct)).ToDictionary(x=>x.Id);return rows.OrderByDescending(x=>x.LastWorkingDate).Where(x=>emps.ContainsKey(x.EmployeeId)).Select(x=>EosMapping.ToDto(x,emps[x.EmployeeId],ls.Where(l=>l.EndOfServiceSettlementId==x.Id).ToArray(),al.Where(a=>a.TargetDocumentId==x.Id).ToArray())).ToArray();} }
public sealed class GetEndOfServiceSettlementByIdQueryHandler(IReadRepository<EndOfServiceSettlement,Guid> settlements,IReadRepository<EndOfServiceSettlementLine,Guid> lines,IReadRepository<Employee,Guid> employees,IReadRepository<PaymentAllocation,Guid> allocations):IRequestHandler<GetEndOfServiceSettlementByIdQuery,EndOfServiceSettlementDto>
{ public async Task<EndOfServiceSettlementDto> Handle(GetEndOfServiceSettlementByIdQuery r,CancellationToken ct){var x=await settlements.GetByIdAsync(r.Id,ct)??throw new NotFoundException(nameof(EndOfServiceSettlement),r.Id);var e=await employees.GetByIdAsync(x.EmployeeId,ct)??throw new NotFoundException(nameof(Employee),x.EmployeeId);var ls=await lines.ListAsync(new Specification<EndOfServiceSettlementLine>().Where(l=>l.EndOfServiceSettlementId==x.Id),ct);var al=await allocations.ListAsync(new Specification<PaymentAllocation>().Where(a=>a.TargetDocumentType==AllocationTargetDocumentType.EndOfServiceSettlement&&a.TargetDocumentId==x.Id),ct);return EosMapping.ToDto(x,e,ls,al);} }

public sealed class CreateEndOfServiceSettlementCommandHandler(IRepository<EndOfServiceSettlement,Guid> settlements,IReadRepository<Employee,Guid> employees,IReadRepository<EmployeeContract,Guid> contracts,IReadRepository<EmployeePayroll,Guid> payrolls,IReadRepository<PayrollRun,Guid> runs,IHRAccountingReferencePort accounting,ISequenceNumberGenerator seq):IRequestHandler<CreateEndOfServiceSettlementCommand,Guid>
{ public async Task<Guid> Handle(CreateEndOfServiceSettlementCommand r,CancellationToken ct){var d=r.Request;var employee=await employees.GetByIdAsync(d.EmployeeId,ct)??throw new NotFoundException(nameof(Employee),d.EmployeeId);if(await settlements.CountAsync(new Specification<EndOfServiceSettlement>().Where(x=>x.EmployeeId==employee.Id&&x.Status!=EndOfServiceStatus.Cancelled),ct)>0)throw new ConflictException("eos_exists","An active end-of-service settlement already exists for this employee.");EmployeeContract? contract=null;if(d.ContractId.HasValue)contract=await contracts.GetByIdAsync(d.ContractId.Value,ct)??throw new NotFoundException(nameof(EmployeeContract),d.ContractId.Value);else contract=(await contracts.ListAsync(new Specification<EmployeeContract>().Where(x=>x.EmployeeId==employee.Id&&x.Status==EmploymentContractStatus.Terminated),ct)).OrderByDescending(x=>x.TerminationEffectiveDate).FirstOrDefault();if(contract is null||contract.EmployeeId!=employee.Id||contract.Status!=EmploymentContractStatus.Terminated||contract.TerminationEffectiveDate!=d.LastWorkingDate)throw new ConflictException("eos_terminated_contract_required","A terminated employee contract with the same last working date is required.");EmployeePayroll? finalPayroll=null;if(d.FinalEmployeePayrollId.HasValue)finalPayroll=await payrolls.GetByIdAsync(d.FinalEmployeePayrollId.Value,ct)??throw new NotFoundException(nameof(EmployeePayroll),d.FinalEmployeePayrollId.Value);else finalPayroll=(await payrolls.ListAsync(new Specification<EmployeePayroll>().Where(x=>x.EmployeeId==employee.Id&&x.Status==EmployeePayrollStatus.Posted&&x.CoverageTo>=d.LastWorkingDate),ct)).OrderByDescending(x=>x.CoverageTo).FirstOrDefault();if(finalPayroll is null||finalPayroll.EmployeeId!=employee.Id||finalPayroll.Status!=EmployeePayrollStatus.Posted||finalPayroll.CoverageTo<d.LastWorkingDate)throw new ConflictException("eos_final_payroll_required","A posted final payroll covering the last working date is required before end-of-service settlement.");var finalRun=await runs.GetByIdAsync(finalPayroll.PayrollRunId,ct)??throw new ConflictException("eos_final_payroll_run_missing","Final payroll run does not exist.");if(finalRun.RunType!=PayrollRunType.Final)throw new ConflictException("eos_final_payroll_type_required","End-of-service settlement requires a posted Final payroll run.");var currency=await accounting.GetCurrencyAsync(finalPayroll.CurrencyId,ct)??throw new ConflictException("currency_not_found","End-of-service currency does not exist.");var n=await seq.NextAsync("EndOfServiceCodeSequence",ct);var x=EndOfServiceSettlement.Create(Guid.NewGuid(),$"EOS-{d.LastWorkingDate.Year:0000}-{n:000000}",employee.Id,contract.Id,finalPayroll.Id,d.LastWorkingDate,currency.Id,currency.Code,currency.Symbol,currency.DecimalPlaces,d.Reason);await settlements.AddAsync(x,ct);return x.Id;} }

public sealed class CalculateEndOfServiceSettlementCommandHandler(IRepository<EndOfServiceSettlement,Guid> settlements,IRepository<EndOfServiceSettlementLine,Guid> lines,IReadRepository<Employee,Guid> employees,IReadRepository<EmployeeContract,Guid> contracts,IReadRepository<EmployeePayroll,Guid> payrolls,IReadRepository<PayrollRun,Guid> runs,IReadRepository<PaymentAllocation,Guid> allocations,IReadRepository<LeaveType,Guid> leaveTypes,IReadRepository<EmployeeLeaveBalance,Guid> leaveBalances,IReadRepository<EmployeeLoan,Guid> loans,IReadRepository<EmployeeLoanInstallment,Guid> installments,IEndOfServiceCalculationPolicy policy,ICurrentUser user,TimeProvider time):IRequestHandler<CalculateEndOfServiceSettlementCommand,Guid>
{ public async Task<Guid> Handle(CalculateEndOfServiceSettlementCommand r,CancellationToken ct){var x=await settlements.GetForUpdateAsync(r.Id,ct)??throw new NotFoundException(nameof(EndOfServiceSettlement),r.Id);EosMapping.Check(r.Request.RowVersion,x.RowVersion);if(x.Status is EndOfServiceStatus.Posted or EndOfServiceStatus.Paid)throw new ConflictException("eos_immutable","Posted end-of-service settlement cannot be recalculated.");var employee=await employees.GetByIdAsync(x.EmployeeId,ct)??throw new NotFoundException(nameof(Employee),x.EmployeeId);var contract=x.ContractId.HasValue?await contracts.GetByIdAsync(x.ContractId.Value,ct):null;if(contract is null||contract.TerminationEffectiveDate!=x.LastWorkingDate)throw new ConflictException("eos_contract_invalid","Terminated contract no longer matches settlement.");var finalPayroll=x.FinalEmployeePayrollId.HasValue?await payrolls.GetByIdAsync(x.FinalEmployeePayrollId.Value,ct):null;if(finalPayroll is null||finalPayroll.Status!=EmployeePayrollStatus.Posted)throw new ConflictException("eos_final_payroll_required","Posted final payroll is required.");var finalRun=await runs.GetByIdAsync(finalPayroll.PayrollRunId,ct)??throw new ConflictException("eos_final_payroll_run_missing","Final payroll run does not exist.");if(finalRun.RunType!=PayrollRunType.Final)throw new ConflictException("eos_final_payroll_type_required","End-of-service settlement requires a Final payroll run.");var existingAllocs=await allocations.ListAsync(new Specification<PaymentAllocation>().Where(a=>a.TargetDocumentType==AllocationTargetDocumentType.EmployeePayroll&&a.TargetDocumentId==finalPayroll.Id),ct);var outstandingPayroll=Math.Max(0m,finalPayroll.NetPay-existingAllocs.Sum(a=>a.AllocatedAmount));var calculationInput=new EndOfServiceCalculationInput(employee.Id,employee.HireDate??contract.StartDate,x.LastWorkingDate,finalPayroll.ConfiguredBasicSalarySnapshot,r.Request.EndOfServiceBenefitAmount,r.Request.LeaveDailyRate);var benefit=await policy.CalculateBenefitAsync(calculationInput,ct);var old=await lines.ListAsync(new Specification<EndOfServiceSettlementLine>().Where(l=>l.EndOfServiceSettlementId==x.Id).Tracking(),ct);if(old.Count>0)lines.DeleteRange(old);var created=new List<EndOfServiceSettlementLine>();var n=1;decimal leaveAmount=0,loanDeduction=0;if(r.Request.SettleEncashableLeave){var types=(await leaveTypes.ListAsync(cancellationToken:ct)).Where(t=>t.IsEncashableOnTermination).ToDictionary(t=>t.Id);var balances=await leaveBalances.ListAsync(new Specification<EmployeeLeaveBalance>().Where(b=>b.EmployeeId==employee.Id),ct);var dailyRate=await policy.CalculateLeaveDailyRateAsync(calculationInput,ct);foreach(var b in balances.Where(b=>types.ContainsKey(b.LeaveTypeId)&&b.AvailableDays>0)){var amount=Math.Round(b.AvailableDays*dailyRate,x.CurrencyDecimalPlacesSnapshot,MidpointRounding.AwayFromZero);if(amount<=0)continue;leaveAmount+=amount;created.Add(EndOfServiceSettlementLine.Create(Guid.NewGuid(),x.Id,n++,EndOfServiceLineType.LeaveSettlement,$"تسوية رصيد إجازة - {types[b.LeaveTypeId].NameAr}","EmployeeLeaveBalance",b.Id,b.AvailableDays,dailyRate,amount,HRPostingRoles.LeaveSettlementExpense,HRPostingRoles.EndOfServicePayable));}}
if(benefit>0)created.Add(EndOfServiceSettlementLine.Create(Guid.NewGuid(),x.Id,n++,EndOfServiceLineType.EndOfServiceBenefit,"مستحق نهاية الخدمة",null,null,null,null,benefit,HRPostingRoles.EndOfServiceExpense,HRPostingRoles.EndOfServicePayable));if(r.Request.OtherEarningsAmount>0)created.Add(EndOfServiceSettlementLine.Create(Guid.NewGuid(),x.Id,n++,EndOfServiceLineType.OtherEarning,"مستحقات أخرى",null,null,null,null,r.Request.OtherEarningsAmount,HRPostingRoles.OtherPayrollExpense,HRPostingRoles.EndOfServicePayable));if(r.Request.SettleOutstandingLoans){var loanIds=(await loans.ListAsync(new Specification<EmployeeLoan>().Where(l=>l.EmployeeId==employee.Id&&l.Status==EmployeeLoanStatus.Active&&l.CurrencyId==x.CurrencyId),ct)).Select(l=>l.Id).ToHashSet();var due=await installments.ListAsync(new Specification<EmployeeLoanInstallment>().Where(i=>loanIds.Contains(i.EmployeeLoanId)&&i.Status==LoanInstallmentStatus.Scheduled),ct);foreach(var i in due){loanDeduction+=i.Amount;created.Add(EndOfServiceSettlementLine.Create(Guid.NewGuid(),x.Id,n++,EndOfServiceLineType.LoanDeduction,"تسوية قسط/رصيد سلفة","EmployeeLoanInstallment",i.Id,1m,i.Amount,i.Amount,HRPostingRoles.EndOfServicePayable,HRPostingRoles.EmployeeLoansReceivable));}}
if(r.Request.OtherDeductionsAmount>0)created.Add(EndOfServiceSettlementLine.Create(Guid.NewGuid(),x.Id,n++,EndOfServiceLineType.OtherDeduction,"خصومات أخرى",null,null,null,null,r.Request.OtherDeductionsAmount,HRPostingRoles.EndOfServicePayable,HRPostingRoles.OtherDeductionsPayable));if(created.Count>0)await lines.AddRangeAsync(created,ct);x.SetCalculated(outstandingPayroll,leaveAmount,benefit,r.Request.OtherEarningsAmount,loanDeduction,r.Request.OtherDeductionsAmount,user.UserId,time.GetUtcNow());settlements.Update(x);return x.Id;} }

public sealed class ReviewEndOfServiceSettlementCommandHandler(IRepository<EndOfServiceSettlement,Guid> repo,ICurrentUser user,TimeProvider time):IRequestHandler<ReviewEndOfServiceSettlementCommand,Guid>
{ public async Task<Guid> Handle(ReviewEndOfServiceSettlementCommand r,CancellationToken ct){var x=await repo.GetForUpdateAsync(r.Id,ct)??throw new NotFoundException(nameof(EndOfServiceSettlement),r.Id);EosMapping.Check(r.Request.RowVersion,x.RowVersion);x.Review(user.UserId,time.GetUtcNow());repo.Update(x);return x.Id;} }
public sealed class ApproveEndOfServiceSettlementCommandHandler(IRepository<EndOfServiceSettlement,Guid> repo,ICurrentUser user,TimeProvider time):IRequestHandler<ApproveEndOfServiceSettlementCommand,Guid>
{ public async Task<Guid> Handle(ApproveEndOfServiceSettlementCommand r,CancellationToken ct){var x=await repo.GetForUpdateAsync(r.Id,ct)??throw new NotFoundException(nameof(EndOfServiceSettlement),r.Id);EosMapping.Check(r.Request.RowVersion,x.RowVersion);x.Approve(user.UserId,time.GetUtcNow());repo.Update(x);return x.Id;} }
public sealed class PostEndOfServiceSettlementCommandHandler(IRepository<EndOfServiceSettlement,Guid> settlements,IReadRepository<EndOfServiceSettlementLine,Guid> lines,IRepository<EmployeeLeaveBalance,Guid> balances,IRepository<EmployeeLoanInstallment,Guid> installments,IHREndOfServiceAccountingPort accounting,ICurrentUser user,TimeProvider time):IRequestHandler<PostEndOfServiceSettlementCommand,Guid>
{ public async Task<Guid> Handle(PostEndOfServiceSettlementCommand r,CancellationToken ct){var x=await settlements.GetForUpdateAsync(r.Id,ct)??throw new NotFoundException(nameof(EndOfServiceSettlement),r.Id);EosMapping.Check(r.Request.RowVersion,x.RowVersion);if(x.Status!=EndOfServiceStatus.Approved)throw new ConflictException("eos_not_approved","Settlement must be approved before posting.");var ls=await lines.ListAsync(new Specification<EndOfServiceSettlementLine>().Where(l=>l.EndOfServiceSettlementId==x.Id),ct);var posting=ls.Where(l=>l.Amount>0).Select(l=>new EndOfServicePostingLine(x.EmployeeId,l.Amount,l.LineType is EndOfServiceLineType.LoanDeduction or EndOfServiceLineType.OtherDeduction,l.DebitPostingRole??string.Empty,l.CreditPostingRole??string.Empty,l.Description,l.SourceDocumentId)).ToArray();var posted=await accounting.PostAsync(new EndOfServicePostingRequest(x.Id,x.SettlementCode,x.LastWorkingDate,x.CurrencyId,posting),ct);x.SetPostingSnapshot(posted.ExchangeRate,posted.ExchangeRateDate,posted.ExchangeRateType,posted.ExchangeRateSource,posted.BaseGross,posted.BaseNet);var now=time.GetUtcNow();foreach(var line in ls){if(line.LineType==EndOfServiceLineType.LeaveSettlement&&line.SourceDocumentId.HasValue&&line.Quantity.HasValue){var b=await balances.GetForUpdateAsync(line.SourceDocumentId.Value,ct)??throw new ConflictException("eos_leave_balance_missing","A leave balance used by the settlement no longer exists.");b.Settle(line.Quantity.Value);balances.Update(b);}if(line.LineType==EndOfServiceLineType.LoanDeduction&&line.SourceDocumentId.HasValue){var i=await installments.GetForUpdateAsync(line.SourceDocumentId.Value,ct)??throw new ConflictException("eos_loan_installment_missing","A loan installment used by the settlement no longer exists.");i.MarkDeductedAtEndOfService(x.Id,now);installments.Update(i);}}x.MarkPosted(posted.JournalEntryId,user.UserId,now);settlements.Update(x);return x.Id;} }
public sealed class PayEndOfServiceSettlementCommandHandler(IRepository<EndOfServiceSettlement,Guid> settlements,IReadRepository<Employee,Guid> employees,IHREndOfServicePaymentPort payments,IReadRepository<PaymentAllocation,Guid> allocations,IEmployeeHrOperationLock gate):IRequestHandler<PayEndOfServiceSettlementCommand,Guid>
{ public async Task<Guid> Handle(PayEndOfServiceSettlementCommand r,CancellationToken ct){var x=await settlements.GetForUpdateAsync(r.Id,ct)??throw new NotFoundException(nameof(EndOfServiceSettlement),r.Id);if(x.Status!=EndOfServiceStatus.Posted)throw new ConflictException("eos_not_posted","Settlement must be posted before payment.");await gate.AcquireAsync(x.EmployeeId,ct);var e=await employees.GetByIdAsync(x.EmployeeId,ct)??throw new NotFoundException(nameof(Employee),x.EmployeeId);var d=r.Request;var existing=await allocations.ListAsync(new Specification<PaymentAllocation>().Where(a=>a.TargetDocumentType==AllocationTargetDocumentType.EndOfServiceSettlement&&a.TargetDocumentId==x.Id),ct);var paidBefore=existing.Sum(a=>a.AllocatedAmount);var payment=await payments.PayAsync(new EndOfServicePaymentPortRequest(x.Id,x.EmployeeId,e.DisplayName,d.PaymentDate,d.Amount,d.PaymentMethod,d.CashAccountId,d.BankAccountId,d.SettlementAccountId,d.ExchangeRate,d.ExchangeRateType,d.ReferenceNumber,d.Description),ct);if(paidBefore+d.Amount>=x.NetSettlementAmount){x.MarkPaid();settlements.Update(x);}return payment.PaymentVoucherId;} }
public sealed class CompleteEndOfServiceSettlementCommandHandler(IRepository<EndOfServiceSettlement,Guid> settlements,IRepository<Employee,Guid> employees,IHREmployeeIdentityPort identity,IReadRepository<PaymentAllocation,Guid> allocations):IRequestHandler<CompleteEndOfServiceSettlementCommand,Guid>
{ public async Task<Guid> Handle(CompleteEndOfServiceSettlementCommand r,CancellationToken ct){var x=await settlements.GetForUpdateAsync(r.Id,ct)??throw new NotFoundException(nameof(EndOfServiceSettlement),r.Id);EosMapping.Check(r.Request.RowVersion,x.RowVersion);if(x.Status!=EndOfServiceStatus.Paid){var all=await allocations.ListAsync(new Specification<PaymentAllocation>().Where(a=>a.TargetDocumentType==AllocationTargetDocumentType.EndOfServiceSettlement&&a.TargetDocumentId==x.Id),ct);if(all.Sum(a=>a.AllocatedAmount)<x.NetSettlementAmount)throw new ConflictException("eos_not_paid","End-of-service settlement must be fully paid before completion.");x.MarkPaid();settlements.Update(x);}var e=await employees.GetForUpdateAsync(x.EmployeeId,ct)??throw new NotFoundException(nameof(Employee),x.EmployeeId);e.SetActive(false);employees.Update(e);if(e.UserAccountId.HasValue)await identity.DisableLinkedUserAsync(e.Id,ct);return x.Id;} }
